from __future__ import annotations

def discoverable_fraction(budget: int, prefix_size: int) -> float:
    if budget < 0 or prefix_size < 0:
        raise ValueError("inputs must be nonnegative")
    return 0.0 if prefix_size == 0 else min(budget, prefix_size) / prefix_size

if __name__ == "__main__":
    budget = 1_000
    for n in (10, 100, 1_000, 10_000, 100_000, 1_000_000):
        print(f"n={n:>8,}  fraction={discoverable_fraction(budget, n):.6g}")

from __future__ import annotations
from math import floor, pi

def holographic_budget(a: float, mass: float) -> int:
    return max(0, floor(pi * a**2 * mass**2))

def fraction(budget: int, n: int) -> float:
    return min(budget, n) / n if n else 0.0

if __name__ == "__main__":
    budget = holographic_budget(2.0, 10.0)
    print("finite capacity:", budget)
    for multiple in (1, 10, 100, 1_000, 10_000):
        n = multiple * budget
        print(f"prefix={n:>10,}  fraction={fraction(budget, n):.6g}")

