from __future__ import annotations
from itertools import product
from typing import Iterator

def enumerate_strings(alphabet_size: int, max_length: int) -> Iterator[tuple[int, ...]]:
    if alphabet_size < 1 or max_length < 0:
        raise ValueError("alphabet_size >= 1 and max_length >= 0 required")
    alphabet = range(alphabet_size)
    for length in range(max_length + 1):
        yield from product(alphabet, repeat=length)

if __name__ == "__main__":
    for statement in enumerate_strings(2, 3):
        print(statement)

from __future__ import annotations
from collections.abc import Iterable, Iterator

def coverage_profile(budget: int, prefixes: Iterable[int]) -> Iterator[tuple[int, int, float]]:
    if budget < 0:
        raise ValueError("budget must be nonnegative")
    for n in prefixes:
        if n < 0:
            raise ValueError("prefixes must be nonnegative")
        reachable = min(budget, n)
        yield n, reachable, 0.0 if n == 0 else reachable / n

if __name__ == "__main__":
    print(*coverage_profile(1000, (100, 1000, 10000, 100000)), sep="\n")

from __future__ import annotations
from collections.abc import Iterable, Iterator

def compare_storage(k: float, c: float, masses: Iterable[float]) -> Iterator[tuple[float, float, float, bool]]:
    if k <= 0.0 or c < 0.0:
        raise ValueError("require k > 0 and c >= 0")
    threshold = c / k
    for mass in masses:
        if mass < 0.0:
            raise ValueError("masses must be nonnegative")
        yield mass, c * mass, k * mass**2, mass >= threshold

if __name__ == "__main__":
    print(*compare_storage(3.0, 24.0, (4.0, 8.0, 16.0, 80.0)), sep="\n")

